95			c.Response().Header().Set("Pragma", "no-cache")
96			c.Response().Header().Set("Expires", "0")
97			return
98		}
99	
100		cacheControl := frontendStaticAssetCacheControl
101		if strings.HasPrefix(requestPath, "/assets/") {
102			cacheControl = frontendHashedAssetCacheControl
103		}
104		c.Response().Header().Set(echo.HeaderCacheControl, cacheControl)
